# fmt: on

import os
import json
from copy import deepcopy


def update_mapping(
    base_dir,
    model_name,
    material_names,
    mapping,
    missing_materials,
    unique_materials_count,
):
    # Initialize the model entries in the mapping with None
    for material_name in material_names:
        if material_name not in mapping:
            mapping[material_name] = {}
        mapping[material_name][model_name] = None

    found_materials = set()

    for folder_index in os.listdir(base_dir):
        folder_path = os.path.join(base_dir, folder_index)
        if os.path.isdir(folder_path):
            for version in os.listdir(folder_path):
                version_path = os.path.join(folder_path, version)
                if os.path.isdir(version_path):
                    for file_name in os.listdir(version_path):
                        for material_name in material_names:
                            if material_name in file_name:
                                mapping[material_name][model_name] = int(folder_index)
                                found_materials.add(material_name)
                                break

    # Update missing materials and unique materials count
    missing_materials[model_name] = [
        material for material in material_names if material not in found_materials
    ]
    unique_materials_count[model_name] = len(found_materials)


def main():
    model_dirs = {
        # "chgnet_dgl": "/store/nosnap/mlip-eval/results/simulation_results_matgl/chgnet_dgl/",
        # "m3gnet_dgl": "/store/nosnap/mlip-eval/results/simulation_results_matgl/m3gnet_dgl/",
        # "mace": "/store/nosnap/mlip-eval/results/mace_simulation_results/mace_pyg",
        # "orb": "/share/datasets-05/aimat_uip/uip_results_0/orb",
        # "sevennet": "/share/datasets-05/aimat_uip/uip_results_0/sevennet",
        "mattersim": "/store/nosnap/mlip-eval/results/mattersim",
    }

    mapping_dir = "./mappings/"
    if os.path.exists(f"{mapping_dir}/material_to_index.json"):
        with open(f"{mapping_dir}/material_to_index.json", "r") as f:
            mapping = json.load(f)
    else:
        mapping = {}

    # Load existing missing materials if it exists
    if os.path.exists(f"{mapping_dir}/missing_materials.json"):
        with open(f"{mapping_dir}/missing_materials.json", "r") as f:
            missing_materials = json.load(f)
    else:
        missing_materials = {}

    # Load existing unique materials count if it exists
    if os.path.exists(f"{mapping_dir}/unique_materials_count.json"):
        with open(f"{mapping_dir}/unique_materials_count.json", "r") as f:
            unique_materials_count = json.load(f)
    else:
        unique_materials_count = {}

    for model_name, model_dir in model_dirs.items():
        update_mapping(
            model_dir,
            model_name,
            material_names,
            mapping,
            missing_materials,
            unique_materials_count,
        )

    # Save the results to JSON files
    with open(f"{mapping_dir}/material_to_index.json", "w") as f:
        json.dump(mapping, f, indent=4)

    # Save updated missing materials
    with open(f"{mapping_dir}/missing_materials.json", "w") as f:
        json.dump(missing_materials, f, indent=4)

    # Save updated unique materials count
    with open(f"{mapping_dir}/unique_materials_count.json", "w") as f:
        json.dump(unique_materials_count, f, indent=4)

    # Find common materials
    intersection_mapping = deepcopy(mapping)
    common_materials = []
    for material, models in mapping.items():
        if all(index is not None for index in models.values()):
            common_materials.append(material)
        else:
            intersection_mapping.pop(material)

    with open(f"{mapping_dir}/intersection_mapping.json", "w") as f:
        json.dump(intersection_mapping, f, indent=4)

    # Save common materials to a JSON file
    with open(f"{mapping_dir}/common_materials.json", "w") as f:
        json.dump(common_materials, f, indent=4)

    print("Mapping:")
    print(mapping)
    print("\nMissing Materials:")
    print(missing_materials)
    print("\nUnique Materials Count:")
    print(unique_materials_count)
    print("\nNumber of Common Materials:")
    print(len(common_materials))


if __name__ == "__main__":
    main()
